import type { Grade, SubjectId } from "@/lib/types";

/*
  One YouTube video for each lesson, chosen and checked by hand.

  How each entry was checked: the video id was looked up with YouTube's own embed lookup (oEmbed), which confirmed the
  video exists and can be embedded, and returned the exact title and channel stored here. Nothing is downloaded or copied:
  the lesson page embeds the video from YouTube, and credits the title and channel.

  Run `npm run check:videos` to check every entry again. Videos can be removed or made private by their owners at any time.
  `captions` records what captions YouTube offered when the video was checked (creator-made, automatic, or none).
  `note` is a caveat for the teacher (advanced vocabulary, a regional curriculum, difficult subject matter).
  Add more videos, or change these, from the editor desk (/studio). Videos listed here are read-only there.
*/
export type CuratedVideo = {
  caseId: string;
  clueId: string;
  grade: Grade;
  subject: SubjectId;
  /** The lesson's own title */
  lesson: string;
  youtubeId: string;
  /** The video's title exactly as YouTube reports it */
  sourceTitle: string;
  channel: string;
  /** Why it fits this lesson */
  why: string;
  note: string;
  /** What captions YouTube offers for this video (checked when the video was added) */
  captions: string;
};

